import{apiClient}from"./client";const getOrganizations=async()=>{return(await apiClient.get("/admin/organizations")).data},createOrganization=async a=>{return(await apiClient.post("/admin/organizations",a)).data},deleteOrganization=async a=>{return(await apiClient.delete("/admin/organizations/"+a)).data},updateOrganization=async(a,t)=>{return(await apiClient.put("/admin/organizations/"+a,t)).data};export{getOrganizations,createOrganization,deleteOrganization,updateOrganization};